function.arguments:
{"command": "cat > cmatrix.c << 'CMATRIX_EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <termios.h>
#include <signal.h>
#include <ctype.h>

#define VERSION "2.0"
#define DEFAULT_DELAY 4
#define MAX_DELAY 10
#define MIN_DELAY 0

static int async_scroll = 0;
static int bold_chars = 0;
static int all_bold = 0;
static int no_bold = 0;
static int linux_mode = 0;
static int old_style = 0;
static int only_shadows = 0;
static int lock_mode = 0;
static int rainbow_mode = 0;
static int lambda_mode = 0;
static int characters_change = 0;
static int x_mode = 0;
static int screensaver_mode = 0;
static int force_term = 0;
static int use_japanese = 0;
static char message[256] = "";
static char color[16] = "green";
static int delay = DEFAULT_DELAY;

static struct termios orig_termios;

static void sigwinch_handler(int sig) { (void)sig; }
static void sigint_handler(int sig) { (void)sig; if (screensaver_mode) exit(0); }
static void sigquit_handler(int sig) { (void)sig; if (screensaver_mode) exit(0); }

static int random_char_index(void) { return rand() % 37; }
static char get_random_char(void) { return "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[random_char_index()]; }
static char get_shadow_char(void) { return "01"[random_char_index()]; }
static char get_bold_char(void) { return "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[random_char_index()]; }
static char get_rainbow_char(void) { return "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[random_char_index()]; }
static char get_change_char(void) { return "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"[random_char_index()]; }
static char get_lambda_char(void) { return 'λ'; }

static void setup_terminal(void) {
    struct termios raw;
    tcgetattr(STDOUT_FILENO, &orig_termios);
    raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON);
    raw.c_cflag |= (CS8 | CLOCAL | CREAD);
    raw.c_iflag &= ~(IXON | IXOFF | IXANY);
    raw.c_oflag &= ~OPOST;
    tcsetattr(STDOUT_FILENO, TCSANOW, &raw);
    signal(SIGWINCH, sigwinch_handler);
    signal(SIGINT, sigint_handler);
    signal(SIGQUIT, sigquit_handler);
}

static void restore_terminal(void) {
    tcsetattr(STDOUT_FILENO, TCSANOW, &orig_termios);
}

static void print_help(void) {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\n");
    printf(" -a: Asynchronous scroll\n");
    printf(" -b: Bold characters on\n");
    printf(" -B: All bold characters (overrides -b)\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\n");
    printf(" -f: Force the linux $TERM type to be on\n");
    printf(" -l: Linux mode (uses matrix console font)\n");
    printf(" -L: Lock mode (can be closed from another terminal)\n");
    printf(" -o: Use old-style scrolling\n");
    printf(" -h: Print usage and exit\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\n");
    printf(" -s: \"Screensaver\" mode, exits on first keystroke\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\n");
    printf(" -V: Print version information and exit\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\n");
    printf(" -C [color]: Use this color for matrix (default green)\n");
    printf(" -r: rainbow mode\n");
    printf(" -m: lambda mode\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\n");
    printf(" -t [tty]: Set tty to use\n");
}

static void print_version(void) {
    printf(" CMatrix version 2.0 (compiled 22:13:51, Jun 11 2026)\n");
    printf("Email: abishekvashok@gmail.com\n");
    printf("Web: https://github.com/abishekvashok/cmatrix\n");
}

static void print_message(void) {
    if (strlen(message) > 0) {
        printf("%s\n", message);
    }
}

static void print_shadow(void) {
    int i, j;
    for (i = 0; i < 3; i++) {
        printf("\033[%d;1H", 24 - i);
        for (j = 0; j < 80; j++) {
            printf("%c", get_shadow_char());
        }
        printf("\033[%d;1H", 24 - i);
    }
}

static void print_bold(void) {
    int i, j;
    for (i = 0; i < 3; i++) {
        printf("\033[%d;1H", 24 - i);
        for (j = 0; j < 80; j++) {
            printf("%c", get_bold_char());
        }
        printf("\033[%d;1H", 24 - i);
    }
}

static void print_rainbow(void) {
